SELECT p.gender, p.age, s.first_careunit, s.los, COUNT(DISTINCT i.procedure_id) AS num_procedures, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY COUNT(DISTINCT i.procedure_id)) AS p75_procedures, PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY COUNT(DISTINCT i.procedure_id)) AS p90_procedures, AVG(s.los) AS avg_los, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS inhospital_mortality_rate FROM patients p JOIN icustays s ON p.subject_id = s.subject_id JOIN diagnoses_icd d ON s.subject_id = d.subject_id JOIN procedures_icd i ON s.subject_id = i.subject_id WHERE p.gender = 'F' AND p.age BETWEEN 37 AND 47 AND s.first_careunit = 'ICU' AND d.icd_code = '426.0' AND i.chartdate BETWEEN s.intime AND s.outtime AND i.procedure_id IN (SELECT procedure_id FROM procedures_icd WHERE chartdate BETWEEN s.intime AND s.outtime) GROUP BY p.gender, p.age, s.first_careunit, s.los;